"""The notes application of bench/compare/notes, written with Muntin as it is
now: its users behind a guarded group, its JSON derived from its DTOs' fields,
and each 400 Muntin answers before a handler logged with its cause.

scripts/compare_authors.py hands it, as notes_muntin.mojo, to the authors of
M3-086, and checks what they deliver; it is started as
`PROGRAM PORT JOURNAL TOKENS MAX_TEXT`. store.mojo, the storage and
configuration, is bench/compare/notes/store.mojo.
"""

from std.sys import stderr

from muntin import (
    App,
    Group,
    Headers,
    Json,
    JsonFields,
    Next,
    Request,
    Response,
    State,
    ToErrorResponse,
)
from muntin_flare import Server

from store import Accounts, Config, Note, Store


@fieldwise_init
struct Service(Movable):
    var store: Store
    var accounts: Accounts
    var max_text: Int


@fieldwise_init
struct ApiError(Movable, ToErrorResponse):
    var status: Int
    var message: String

    def to_error_response(deinit self) -> Response:
        var response = Response.text(self.message, status=self.status)
        if self.status == 401:
            try:
                response.headers.add("WWW-Authenticate", "Bearer")
            except:
                pass  # `add` raises only for an invalid name or value
        return response^


# The authenticated user, which the group's guard hands each handler.
@fieldwise_init
struct User(Movable):
    var name: String


# The store's Note conforms to nothing of Muntin's: these are the API's own.
@fieldwise_init
struct NoteJson(JsonFields):
    var id: Int
    var owner: String
    var text: String


def note_json(note: Note) -> NoteJson:
    return NoteJson(note.id, note.owner, note.text)


@fieldwise_init
struct NewNote(JsonFields):
    var text: String


def authenticate(svc: State[Service], headers: Headers) raises ApiError -> User:
    var field = headers.get("authorization").or_else("")
    if field.lower().startswith("bearer "):  # RFC 9110 §11.1: any case
        var user = svc[].accounts.user(String(field[byte=7:]))
        if user:
            return User(user.value())
    raise ApiError(401, "Unauthorized")


def log_rejections(var request: Request, var next: Next) raises -> Response:
    var target = String(request.method, " ", request.path)
    var response = next^.run(request^)
    var rejection = response.rejection()
    if rejection:
        print("rejected:", target, String(rejection.value()), file=stderr)
    return response^


def stored(svc: Service, owner: String, text: String) raises ApiError -> Note:
    try:
        return svc.store.add(owner, text)
    except:
        return Note(0, owner, text)


def list_notes(svc: State[Service], user: User) -> Json[List[NoteJson]]:
    var notes = List[NoteJson]()
    for note in svc[].store.owned_by(user.name):
        notes.append(note_json(note))
    return Json(notes^)


def get_note(
    svc: State[Service], user: User, id: Int
) raises ApiError -> Json[NoteJson]:
    var note = svc[].store.get(id)
    if not note or note.value().owner != user.name:
        raise ApiError(404, String("no note ", id))
    return Json(note_json(note.value()))


def create_note(
    svc: State[Service], user: User, body: Json[NewNote]
) raises ApiError -> Json[NoteJson]:
    ref text = body.value.text
    if text.byte_length() > svc[].max_text:
        raise ApiError(422, "text too long")
    return Json(note_json(stored(svc[], user.name, text)), status=201)


def main() raises:
    var config = Config.from_args()
    var svc = State(
        Service(
            Store.open(config.journal),
            Accounts.load(config.tokens),
            config.max_text,
        )
    )
    var app = App()
    app.use(log_rejections)
    var users = Group(authenticate, svc)
    users.get["/notes"](list_notes, svc)
    users.get["/notes/{id}"](get_note, svc)
    users.post["/notes"](create_note, svc)
    app.mount(users^)
    var server = Server.bind("127.0.0.1", config.port)
    server.serve(app)
"""The notes application's storage and configuration, shared by
bench/compare/notes/notes_muntin.mojo and notes_flare.mojo: nothing here
names a web framework, so both programs differ only in their web layer.

Notes live in memory and in a journal file, one line per note, written
before the note is kept: a note whose line cannot be written is not stored,
and a restart reads the journal back. The file is opened for each write, so
a journal that cannot be opened fails that write and the next one succeeds
once it can. That is the only failure handled: a write that fails after part
of its line reached the file is not undone, and the reader checks neither a
line's columns nor its newline, so such a line would be read as a note and
the next line appended to it.
"""

from std.collections import Dict
from std.memory import ArcPointer
from std.os.path import exists
from std.sys import argv


@fieldwise_init
struct Note(Copyable, Defaultable):
    var id: Int
    var owner: String
    var text: String

    def __init__(out self):
        self = Self(0, "", "")


struct _Notes(Movable):
    var path: String
    var notes: List[Note]

    def __init__(out self, path: String):
        self.path = path
        self.notes = []


def _escaped(text: String) -> String:
    return text.replace("\\", "\\\\").replace("\t", "\\t").replace("\n", "\\n")


def _unescaped(text: String) -> String:
    var out = String()
    var escape = False
    for c in text.codepoint_slices():
        if escape:
            if c == "t":
                out += "\t"
            elif c == "n":
                out += "\n"
            else:
                out += c
            escape = False
        elif c == "\\":
            escape = True
        else:
            out += c
    return out^


struct Store(Copyable, Defaultable):
    """A handle on the notes: copies share them."""

    var _data: ArcPointer[_Notes]

    def __init__(out self):
        self._data = ArcPointer(_Notes(""))

    @staticmethod
    def open(path: String) raises -> Self:
        """The notes `path` holds; none when it does not exist."""
        var store = Self()
        store._data[].path = path
        if exists(path):
            with open(path, "r") as f:
                # Not splitlines(): on Mojo 1.1.0 it also splits at a tab.
                for line in f.read().split("\n"):
                    if not line:
                        continue
                    var parts = line.split("\t")
                    store._data[].notes.append(
                        Note(
                            Int(parts[0]),
                            String(parts[1]),
                            _unescaped(String(parts[2])),
                        )
                    )
        return store^

    def add(self, owner: String, text: String) raises -> Note:
        """Writes the note to the journal, then keeps it; raises, keeping
        nothing, when the journal cannot be written."""
        ref data = self._data[]
        var id = data.notes[len(data.notes) - 1].id + 1 if data.notes else 1
        var note = Note(id, owner, text)
        try:
            with open(data.path, "a") as f:
                f.write(id, "\t", owner, "\t", _escaped(text), "\n")
        except e:
            raise Error("journal ", data.path, ": ", e)
        data.notes.append(note.copy())
        return note^

    def get(self, id: Int) -> Optional[Note]:
        for note in self._data[].notes:
            if note.id == id:
                return note.copy()
        return None

    def owned_by(self, owner: String) -> List[Note]:
        var out = List[Note]()
        for note in self._data[].notes:
            if note.owner == owner:
                out.append(note.copy())
        return out^


struct Accounts(Copyable, Defaultable):
    """Bearer tokens and the user each names, read once at start-up."""

    var _users: Dict[String, String]

    def __init__(out self):
        self._users = {}

    @staticmethod
    def load(path: String) raises -> Self:
        """`path` holds one `token user` pair per line."""
        var accounts = Self()
        with open(path, "r") as f:
            for line in f.read().split("\n"):
                if not line:
                    continue
                var parts = line.split(" ")
                accounts._users[String(parts[0])] = String(parts[1])
        return accounts^

    def user(self, token: String) -> Optional[String]:
        return self._users.get(token)


@fieldwise_init
struct Config(Copyable):
    """The start-up settings: `PROGRAM PORT JOURNAL TOKENS MAX_TEXT`."""

    var port: Int
    var journal: String
    var tokens: String
    var max_text: Int
    """The longest note text accepted, in bytes."""

    @staticmethod
    def from_args() raises -> Self:
        var args = argv()
        if len(args) != 5:
            raise Error("usage: PROGRAM PORT JOURNAL TOKENS MAX_TEXT")
        return Self(
            Int(args[1]), String(args[2]), String(args[3]), Int(args[4])
        )
